'use client';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useParams } from 'next/navigation';
import Link from 'next/link';
import { ArrowLeft, ArrowRight, BookOpen, Check, ChevronDown, CircleAlert, Clapperboard, ClipboardList, Film, Globe2, Image as ImageIcon, Layers3, LoaderCircle, Menu, Play, Plus, RefreshCw, Save, Scissors, Search, Sparkles, Upload, Video, X } from 'lucide-react';
import { API, Clip, Entity, Provider, get, patch, post, remove, request } from '@/lib/api';

const NAV = [
  ['01', '剧本', BookOpen], ['02', '人物与世界', Globe2], ['03', '场次与分镜', Layers3],
  ['04', '影片制作', ClipboardList], ['05', '审片', Play], ['06', '成片', Film]
] as const;
const STRATEGIES = ['INDEPENDENT', 'MULTI_SHOT_ONE_PASS', 'STATE_CONTINUE_NEW_VIEW', 'VISUAL_ANCHOR', 'VIDEO_CONTINUATION', 'KEYFRAME_CONSTRAINED'];
const STRATEGY_NAME: Record<string,string> = { INDEPENDENT:'独立生成', MULTI_SHOT_ONE_PASS:'多镜头一次生成', STATE_CONTINUE_NEW_VIEW:'普通 CUT · 状态连续', VISUAL_ANCHOR:'视觉锚点', VIDEO_CONTINUATION:'视频续接', KEYFRAME_CONSTRAINED:'首尾帧约束' };
const REASONS: Record<string,string> = { BRIEF_MISSING:'还没有最终制作方案', MISSING_FIELD:'制作方案还有内容未填写', SHOT_TIMELINE_MISMATCH:'镜头时间线与当前规划不一致', SHOT_NOT_APPROVED:'请先确认镜头计划', SHOT_INTENT_MISMATCH:'镜头已变化，请更新制作方案', UPSTREAM_CANONICAL_STATE_MISSING:'等待上一片段采用并确认实际状态', STATE_CONTEXT_STALE_OR_MISSING:'上一片段已变化，请重新准备', DURATION_CLIP_MISMATCH:'片段时长与制作方案不一致', UNRESOLVED_SUBJECT:'人物或造型尚未准备', STATE_IN_NOT_RECONSTRUCTABLE:'开始状态还不能确认', ACTION_NOT_PROCESS:'请描述完整动作过程', ABSTRACT_PERFORMANCE:'请写出可见的表演', CAMERA_UNCLEAR:'摄影信息仍需完善', SHOT_TIMELINE_GAP_OR_OVERLAP:'镜头时间线有空隙或重叠' };
function message(error: any) { return error?.message || '操作失败'; }
function prettyReason(r: any) { return REASONS[r.code] || `${r.code}${r.field ? ` · ${r.field}` : ''}`; }
function Empty({ icon: Icon = Sparkles, title, body, action }: { icon?: any; title: string; body: string; action?: React.ReactNode }) { return <div className="empty"><span className="empty-icon"><Icon size={25}/></span><h3>{title}</h3><p>{body}</p>{action}</div>; }
function Badge({ children, tone = 'neutral' }: { children: React.ReactNode; tone?: string }) { return <span className={`badge ${tone}`}>{children}</span>; }
function Field({ label, value, onChange, multiline = false, placeholder = '' }: {label:string; value:string; onChange:(v:string)=>void; multiline?:boolean; placeholder?:string}) { return <label className="field"><span>{label}</span>{multiline ? <textarea value={value} onChange={e=>onChange(e.target.value)} rows={3} placeholder={placeholder}/> : <input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>}</label>; }

export default function Workspace() {
  const params = useParams();
  const pid = String(params.id), space = String(params.space);
  const [project, setProject] = useState<Entity | null>(null);
  const [provider, setProvider] = useState<Provider | null>(null);
  const [scenes, setScenes] = useState<Entity[]>([]);
  const [shots, setShots] = useState<Entity[]>([]);
  const [clips, setClips] = useState<Clip[]>([]);
  const [jobs, setJobs] = useState<any[]>([]);
  const [takes, setTakes] = useState<any[]>([]);
  const [reality, setReality] = useState<Record<string,any>>({});
  const [world, setWorld] = useState<Record<string,Entity[]>>({});
  const [visualPrep, setVisualPrep] = useState<any[]>([]);
  const [timeline, setTimeline] = useState<any>({items:[],subtitles:[]});
  const [impacts, setImpacts] = useState<any[]>([]);
  const [sceneId, setSceneId] = useState('');
  const [clipId, setClipId] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [navOpen, setNavOpen] = useState(false);
  const base = `/projects/${pid}`;
  const load = useCallback(async () => {
    const common = await Promise.all([get<Entity>(`/projects/${pid}`), get<Provider>('/providers'), get<Entity[]>(`${base}/scenes`), get<any[]>(`${base}/impacts`)]);
    setProject(common[0]); setProvider(common[1]); setScenes(common[2]); setImpacts(common[3]);
    setSceneId(old => old && common[2].some(s => s.id === old) ? old : common[2][0]?.id || '');
    if (space === '02') {
      const kinds = ['character','character_look','location','prop','asset_version'];
      const data = await Promise.all(kinds.map(k => get<Entity[]>(`${base}/world/${k}`)));
      setWorld(Object.fromEntries(kinds.map((k,i) => [k,data[i]])));
      setVisualPrep(await get<any[]>(`${base}/visual-prep`));
    }
    if (['03','04','05','06'].includes(space)) {
      const [ss,cc] = await Promise.all([get<Entity[]>(`${base}/shots`),get<Clip[]>(`${base}/clips`)]);
      setShots(ss); setClips(cc);
      setClipId(old => old && cc.some(c => c.id === old) ? old : cc[0]?.id || '');
    }
    if (['04','05','06'].includes(space)) {
      const [jj,tt,rr] = await Promise.all([get<any[]>(`${base}/jobs`),get<any[]>(`${base}/takes`),get<Record<string,any>>(`${base}/reality`)]);
      setJobs(jj);setTakes(tt);setReality(rr);
    }
    if (space === '06') setTimeline(await get<any>(`${base}/timeline`));
  }, [base, pid, space]);
  useEffect(() => { load().catch(e => setError(message(e))); }, [load]);
  const act = async (fn: () => Promise<any>, success = '已保存') => {
    setBusy(true); setError(''); setNotice('');
    try { await fn(); await load(); setNotice(success); } catch (e) { setError(message(e)); } finally { setBusy(false); }
  };
  const scene = scenes.find(s => s.id === sceneId);
  const sceneShots = shots.filter(s => s.payload.scene_id === sceneId && s.status !== 'archived');
  const sceneClips = clips.filter(c => c.payload.scene_id === sceneId);
  const activeClip = clips.find(c => c.id === clipId);
  const spaceTitle = NAV.find(n => n[0] === space)?.[1] || '工作区';
  return <div className="studio-shell">
    <aside className={`sidebar ${navOpen ? 'open' : ''}`}><Link className="sidebar-brand" href="/"><span className="brand-mark"><Clapperboard size={20}/></span><span>AI FILM<br/><strong>STUDIO</strong></span></Link><div className="sidebar-divider"/><div className="nav-kicker">WORKSPACES</div><nav aria-label="工作区导航">{NAV.map(([number,label,Icon]) => <Link key={number} href={`/projects/${pid}/${number}`} onClick={()=>setNavOpen(false)} className={`nav-link ${space === number ? 'active' : ''}`} aria-label={`${number} ${label}`}><span className="nav-number">{number}</span><Icon size={17}/><span>{label}</span>{space === number && <span className="nav-active-dot"/>}</Link>)}</nav><div className="sidebar-bottom"><span className="sidebar-project-label">CURRENT PROJECT</span><div className="sidebar-project-title">{project?.payload.title || '载入中…'}</div><Link href="/" className="back-link"><ArrowLeft size={15}/> 返回影片列表</Link></div></aside>
    <div className="main-area"><header className="topbar"><button className="mobile-menu icon-btn" onClick={()=>setNavOpen(!navOpen)} aria-label="打开导航"><Menu size={20}/></button><div className="breadcrumbs"><span>{project?.payload.title || '影片'}</span><span className="crumb-slash">/</span><strong>{space} {spaceTitle}</strong></div><div className="topbar-right"><span className={`provider-pill ${provider?.h3 === '可用' ? 'online' : 'offline'}`}><span className="status-dot"/> H3 {provider?.h3 || '检查中'}</span><Link className="job-link" href={`/projects/${pid}/04`}><Video size={16}/> 生成任务 {jobs.filter(j=>j.status==='running').length || ''}</Link></div></header>
      <main className="workspace-main"><div className="workspace-header"><div><span className="eyebrow">WORKSPACE {space} / 06</span><h1>{spaceTitle}</h1><p>{({ '01':'写下故事，确定这一场发生什么。','02':'为真正需要的角色、场景和道具建立稳定身份。','03':'把场次变成清晰的导演镜头计划。','04':'把镜头计划变成能执行的最终制作方案。','05':'看真实生成结果，再决定采用哪一条。','06':'把已经采用的片段组织成影片。' } as Record<string,string>)[space]}</p></div><div className="header-actions"><span className="save-state"><span className="status-dot"/>{busy ? '保存中…' : '已连接本地项目'}</span></div></div>
        {error && <div className="alert error" role="alert"><CircleAlert size={17}/>{error}<button onClick={()=>setError('')} aria-label="关闭"><X size={15}/></button></div>}
        {notice && <div className="alert success"><Check size={17}/>{notice}</div>}
        {impacts.length > 0 && ['03','04','05'].includes(space) && <div className="impact-banner"><CircleAlert size={18}/><div><strong>上游内容有变化</strong><span>{impacts[0].message}</span></div></div>}
        {space === '01' && project && <ScriptSpace base={base} project={project} scenes={scenes} act={act}/>}
        {space === '02' && <WorldSpace base={base} world={world} visualPrep={visualPrep} act={act}/>}
        {space === '03' && <ShotSpace base={base} scenes={scenes} scene={scene} sceneId={sceneId} setSceneId={setSceneId} shots={sceneShots} act={act}/>}
        {space === '04' && <ProductionSpace base={base} scenes={scenes} scene={scene} sceneId={sceneId} setSceneId={setSceneId} shots={sceneShots} clips={sceneClips} jobs={jobs} provider={provider} act={act}/>}
        {space === '05' && <ReviewSpace base={base} clips={clips} clipId={clipId} setClipId={setClipId} takes={takes} reality={reality} act={act}/>}
        {space === '06' && <FinalSpace base={base} clips={clips} takes={takes} reality={reality} timeline={timeline} act={act}/>}
      </main></div>
  </div>;
}

function ScriptSpace({base,project,scenes,act}:{base:string;project:Entity;scenes:Entity[];act:any}) {
  const [script,setScript] = useState(project.payload.script || '');
  const [place,setPlace] = useState('');const [story,setStory] = useState('');
  useEffect(()=>setScript(project.payload.script || ''),[project.version,project.payload.script]);
  return <div className="two-column script-layout"><section className="panel editor-panel"><div className="panel-title"><div><span className="small-label">STORY DRAFT · VERSION {project.version}</span><h2>故事原稿</h2></div><Badge>{project.payload.aspect_ratio}</Badge></div><textarea className="script-editor" aria-label="剧本正文" value={script} onChange={e=>setScript(e.target.value)} placeholder="从一句想法开始。写下人物、地点和发生的事……"/><div className="panel-footer"><span>{script.length} 字 · 每次保存保留版本</span><button className="primary" onClick={()=>act(()=>patch(`${base}`,{payload:{script},expected_version:project.version,status:'approved'}),'剧本新版本已保存')}><Save size={16}/> 保存版本</button></div></section>
    <section className="panel scene-panel"><div className="panel-title"><div><span className="small-label">SCENE STRUCTURE</span><h2>场次 <span className="heading-count">{scenes.length}</span></h2></div></div><p className="muted compact">每个场次只描述故事发生什么；镜头设计留给 03。</p>{scenes.length === 0 && <Empty icon={BookOpen} title="还没有场次" body="先写原稿，再把故事切成可以拍摄的场次。"/>}<div className="scene-list">{scenes.map((s,i)=><SceneRow key={s.id} base={base} scene={s} index={i} count={scenes.length} act={act}/>)}</div><div className="inline-create"><Field label="地点 / 时段" value={place} onChange={setPlace} placeholder="例如：雨夜车站"/><Field label="这一场发生什么" value={story} onChange={setStory} multiline placeholder="人物做了什么，故事发生了什么变化？"/><button className="secondary" disabled={!story.trim()} onClick={()=>act(async()=>{await post(`${base}/scenes`,{payload:{place,story,ordinal:scenes.length}});setPlace('');setStory('');},'场次已创建')}><Plus size={16}/> 新增场次</button></div></section></div>;
}
function SceneRow({base,scene,index,count,act}:{base:string;scene:Entity;index:number;count:number;act:any}) {
  const [editing,setEditing]=useState(false); const [story,setStory]=useState(scene.payload.story||'');const [place,setPlace]=useState(scene.payload.place||'');
  const url=`${base}/scenes/${scene.id}`;
  return <div className="scene-row"><div className="scene-row-head"><span className="scene-num">SC {String(index+1).padStart(2,'0')}</span><strong>{scene.payload.place || '未命名场景'}</strong><Badge tone={scene.payload.ready_for_directing?'green':'neutral'}>{scene.payload.ready_for_directing?'可进入导演设计':'草稿'}</Badge></div><p>{scene.payload.story}</p><div className="row-actions"><button onClick={()=>setEditing(!editing)}>编辑</button><button disabled={index===0} onClick={()=>act(()=>patch(url,{payload:{ordinal:(scene.payload.ordinal??index)-1.5},expected_version:scene.version,status:scene.status}),'已调整顺序')}>上移</button><button disabled={index===count-1} onClick={()=>act(()=>patch(url,{payload:{ordinal:(scene.payload.ordinal??index)+1.5},expected_version:scene.version,status:scene.status}),'已调整顺序')}>下移</button><button onClick={()=>act(()=>patch(url,{payload:{ready_for_directing:!scene.payload.ready_for_directing},expected_version:scene.version,status:'approved'}),'场次状态已更新')}>{scene.payload.ready_for_directing?'撤回确认':'进入导演设计'}</button><button className="danger-text" onClick={()=>{if(confirm('归档此场次？关联镜头、Clip 和 Take 的历史不会删除，但下游需要重新确认。')) act(()=>remove(`${url}?expected_version=${scene.version}`),'场次已归档');}}>归档</button></div>{editing && <div className="scene-edit"><Field label="地点" value={place} onChange={setPlace}/><Field label="场次内容" value={story} onChange={setStory} multiline/><button className="primary small" onClick={()=>act(async()=>{await patch(url,{payload:{place,story},expected_version:scene.version,status:scene.status});setEditing(false);})}>保存场次</button></div>}</div>;
}

function WorldSpace({base,world,visualPrep,act}:{base:string;world:Record<string,Entity[]>;visualPrep:any[];act:any}) {
  const [tab,setTab]=useState<'character'|'character_look'|'location'|'prop'>('character');
  const [name,setName]=useState('');const [identity,setIdentity]=useState('');const [description,setDescription]=useState('');
  const [uploadOwner,setUploadOwner]=useState('');const [file,setFile]=useState<File|null>(null);
  const tabs=[['character','人物'],['character_look','造型'],['location','场景'],['prop','道具']] as const;
  const assets=world.asset_version||[];
  return <div className="world-space"><div className="section-intro"><div><h2>视觉身份</h2><p>只准备接下来需要稳定的形象。真实素材会显示在这里，没有素材时保持文字身份。</p></div><Badge tone="gold">JIT VISUAL PREP</Badge></div>{visualPrep.some(x=>x.missing_visual_anchors?.length>0)&&<div className="visual-prep"><ImageIcon size={18}/><div><strong>接下来可准备的视觉锚点</strong><span>{visualPrep.filter(x=>x.missing_visual_anchors?.length).map(x=>`${x.scene||'当前场次'}：${x.missing_visual_anchors.join('、')}`).join('；')}</span></div></div>}<div className="tab-row">{tabs.map(([key,label])=><button key={key} className={tab===key?'selected':''} onClick={()=>setTab(key)}>{label} <span>{world[key]?.length||0}</span></button>)}</div><div className="two-column world-columns"><section className="panel"><div className="panel-title"><h2>{tabs.find(x=>x[0]===tab)?.[1]}身份</h2></div>{!(world[tab]||[]).length && <Empty icon={Globe2} title="这里还没有身份资料" body="添加真正需要保持一致的人物、场景或道具。"/>}<div className="identity-list">{(world[tab]||[]).map(x=><div className="identity-card" key={x.id}><span className="identity-symbol">{tab==='character'?'人':tab==='character_look'?'装':tab==='location'?'景':'物'}</span><div><strong>{x.payload.name||x.payload.identity||x.payload.description}</strong><p>{x.payload.identity||x.payload.description||'尚未补充说明'}</p><span className="small-label">VERSION {x.version} · {assets.filter(a=>a.payload.owner_id===x.id).length} 个真实素材版本</span></div></div>)}</div><div className="inline-create">{tab==='character_look'&&<label className="field"><span>所属人物</span><select value={uploadOwner} onChange={e=>setUploadOwner(e.target.value)}><option value="">选择人物</option>{(world.character||[]).map(x=><option key={x.id} value={x.id}>{x.payload.name}</option>)}</select></label>}<Field label={tab==='character'?'人物名称':tab==='character_look'?'造型名称':'身份名称'} value={name} onChange={setName} placeholder={tab==='character'?'例如：林夏':tab==='character_look'?'例如：雨夜风衣':'例如：旧车站'}/><Field label="身份说明" value={identity} onChange={setIdentity} multiline placeholder="需要在后续片段保持稳定的特征"/><button className="secondary" disabled={!name.trim()||(tab==='character_look'&&!uploadOwner)} onClick={()=>act(async()=>{await post(`${base}/world/${tab}`,{payload:tab==='character'?{name,identity}:tab==='character_look'?{character_id:uploadOwner,description:`${name}：${identity}`}:{identity:name,description:identity}});setName('');setIdentity('');},'身份已保存')}><Plus size={16}/> 添加身份</button></div></section>
  <section className="panel"><div className="panel-title"><div><span className="small-label">REAL ASSETS ONLY</span><h2>素材版本</h2></div></div>{assets.length===0 && <Empty icon={ImageIcon} title="尚无真实视觉素材" body="可以上传角色、场景或道具参考。我们不会用虚构缩略图占位。"/>}<div className="asset-grid">{assets.map(a=><div className="asset-card" key={`${a.id}-${a.version}`}><img src={`${API}/api/media-asset/${a.id}?version=${a.version}`} alt={a.payload.purpose||'上传素材'} loading="lazy"/><div><strong>{a.payload.purpose||'参考素材'}</strong><span>V{a.version}</span></div><button className="ghost small" disabled={a.is_current} onClick={()=>act(()=>post(`${base}/assets/${a.id}/current`,{version:a.version}),"当前素材版本已切换")}>{a.is_current?"当前版本":"设为当前"}</button></div>)}</div><div className="inline-create"><label className="field"><span>关联身份</span><select value={uploadOwner} onChange={e=>setUploadOwner(e.target.value)}><option value="">选择人物、场景或道具</option>{['character','character_look','location','prop'].flatMap(k=>(world[k]||[]).map(x=><option key={x.id} value={x.id}>{x.payload.name||x.payload.identity||x.payload.description}</option>))}</select></label><Field label="用途" value={description} onChange={setDescription} placeholder="例如：当前造型参考"/><label className="upload-label"><Upload size={16}/> 选择真实图片<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>setFile(e.target.files?.[0]||null)}/>{file?.name}</label><button className="secondary" disabled={!uploadOwner||!file} onClick={()=>act(async()=>{const data=new FormData();data.append('file',file!);await request(`${base}/assets/upload?owner_id=${encodeURIComponent(uploadOwner)}&purpose=${encodeURIComponent(description)}`,{method:'POST',body:data});setFile(null);setDescription('');},'素材已上传')}><Upload size={16}/> 上传素材</button></div></section></div></div>;
}

function ShotSpace({base,scenes,scene,sceneId,setSceneId,shots,act}:{base:string;scenes:Entity[];scene?:Entity;sceneId:string;setSceneId:any;shots:Entity[];act:any}) {
  const [description,setDescription]=useState('');const [duration,setDuration]=useState('5');const [purpose,setPurpose]=useState('');const [action,setAction]=useState('');const [performance,setPerformance]=useState('');const [camera,setCamera]=useState('');const [sound,setSound]=useState('');
  return <div className="production-layout"><SceneRail scenes={scenes} sceneId={sceneId} setSceneId={setSceneId}/><div className="production-center"><div className="section-intro"><div><span className="small-label">DIRECTOR SHOT PLAN</span><h2>{scene?.payload.place||'选择场次'}</h2><p>{scene?.payload.story||'先在 01 创建并确认一个场次。'}</p></div><Badge>{shots.length} SHOTS</Badge></div>{!scene && <Empty icon={Layers3} title="先准备一个场次" body="在 01 写下剧本和场次，然后回来设计镜头。"/>}{scene && shots.length===0 && <Empty icon={Layers3} title="还没有镜头计划" body="导演镜头可以长于视频模型的单次时长；制作阶段再规划如何拆分。"/>}<div className="shot-list">{shots.map((shot,i)=><ShotCard key={shot.id} shot={shot} index={i} base={base} act={act}/>)}</div>{scene && <section className="panel new-shot"><div className="panel-title"><div><span className="small-label">ADD DIRECTOR SHOT</span><h2>设计下一镜</h2></div></div><div className="form-grid"><Field label="镜头目的" value={purpose} onChange={setPurpose} placeholder="这一镜为什么存在？"/><Field label="预计时长（秒）" value={duration} onChange={setDuration}/></div><Field label="观众看到什么" value={description} onChange={setDescription} multiline placeholder="主体、空间、镜头画面"/><div className="form-grid"><Field label="动作过程" value={action} onChange={setAction} placeholder="从什么开始，如何变化？"/><Field label="表演" value={performance} onChange={setPerformance} placeholder="目光、呼吸、手势、停顿"/><Field label="摄影" value={camera} onChange={setCamera} placeholder="景别、机位、运动"/><Field label="声音" value={sound} onChange={setSound} placeholder="环境声、对白、音乐"/></div><button className="primary" disabled={!description.trim()||Number(duration)<=0} onClick={()=>act(async()=>{await post(`${base}/shots`,{payload:{scene_id:sceneId,ordinal:shots.length,duration:Number(duration),description,purpose,action,performance,camera,sound}});setDescription('');setPurpose('');setAction('');setPerformance('');setCamera('');setSound('');},'镜头已加入计划')}><Plus size={16}/> 添加镜头</button></section>}</div></div>;
}
function SceneRail({scenes,sceneId,setSceneId}:{scenes:Entity[];sceneId:string;setSceneId:any}) {return <aside className="scene-rail"><div className="small-label">SCENES</div>{scenes.map((s,i)=><button key={s.id} className={sceneId===s.id?'active':''} onClick={()=>setSceneId(s.id)}><span>{String(i+1).padStart(2,'0')}</span><strong>{s.payload.place||`场次 ${i+1}`}</strong></button>)}{scenes.length===0&&<p className="muted">还没有场次</p>}</aside>}
function ShotCard({shot,index,base,act}:{shot:Entity;index:number;base:string;act:any}) {
 const [edit,setEdit]=useState(false);const [description,setDescription]=useState(shot.payload.description||'');const [purpose,setPurpose]=useState(shot.payload.purpose||'');const [duration,setDuration]=useState(String(shot.payload.duration||5));const [action,setAction]=useState(shot.payload.action||'');const [performance,setPerformance]=useState(shot.payload.performance||'');const [camera,setCamera]=useState(shot.payload.camera||'');const [sound,setSound]=useState(shot.payload.sound||'');
 const url=`${base}/shots/${shot.id}`;
 return <article className="shot-card"><div className="shot-top"><span className="shot-index">SHOT {String(index+1).padStart(2,'0')}</span><div className="shot-top-right"><span>{shot.payload.duration}s</span><Badge tone={shot.status==='approved'?'green':'neutral'}>{shot.status==='approved'?'已确认':'待确认'}</Badge></div></div><h3>{shot.payload.purpose||'镜头目的待补充'}</h3><p className="shot-description">{shot.payload.description}</p><div className="shot-details"><span><strong>动作</strong>{shot.payload.action||'待补充'}</span><span><strong>表演</strong>{shot.payload.performance||'待补充'}</span><span><strong>摄影</strong>{shot.payload.camera||'待补充'}</span><span><strong>声音</strong>{shot.payload.sound||'待补充'}</span></div><div className="row-actions"><button onClick={()=>setEdit(!edit)}>{edit?'收起':'修改'}</button><button onClick={()=>act(()=>patch(url,{payload:{director_approved:true},expected_version:shot.version,status:'approved'}),'镜头计划已确认')} disabled={shot.status==='approved'}>确认镜头</button><button onClick={()=>act(()=>patch(url,{payload:{ordinal:(shot.payload.ordinal??index)-1.5},expected_version:shot.version,status:shot.status}),'镜头顺序已更新')}>上移</button><button onClick={()=>{if(confirm('将这条导演镜头拆成两条？已建立的 Clip 需要重新准备。')) act(async()=>{const half=Number((shot.payload.duration/2).toFixed(1));await patch(url,{payload:{duration:half,description:shot.payload.description+'（前半段）'},expected_version:shot.version,status:'draft'});await post(`${base}/shots`,{payload:{...shot.payload,description:shot.payload.description+'（后半段）',duration:shot.payload.duration-half,ordinal:(shot.payload.ordinal??index)+0.5}})},'镜头已拆分，需重新确认');}}><Scissors size={14}/> 拆分</button><button className="danger-text" onClick={()=>{if(confirm('归档此镜头？下游计划将受到影响。')) act(()=>remove(`${url}?expected_version=${shot.version}`),'镜头已归档');}}>归档</button></div>{edit&&<div className="shot-edit"><div className="form-grid"><Field label="镜头目的" value={purpose} onChange={setPurpose}/><Field label="时长" value={duration} onChange={setDuration}/></div><Field label="画面描述" value={description} onChange={setDescription} multiline/><div className="form-grid"><Field label="动作过程" value={action} onChange={setAction}/><Field label="表演" value={performance} onChange={setPerformance}/><Field label="摄影" value={camera} onChange={setCamera}/><Field label="声音" value={sound} onChange={setSound}/></div><button className="primary small" onClick={()=>act(async()=>{await patch(url,{payload:{purpose,duration:Number(duration),description,action,performance,camera,sound,director_approved:false},expected_version:shot.version,status:'draft'});setEdit(false);})}>保存修改</button></div>}</article>;
}
function ProductionSpace({base,scenes,scene,sceneId,setSceneId,shots,clips,jobs,provider,act}:{base:string;scenes:Entity[];scene?:Entity;sceneId:string;setSceneId:any;shots:Entity[];clips:Clip[];jobs:any[];provider:Provider|null;act:any}) {
 const [name,setName]=useState('');const [duration,setDuration]=useState('8');const [strategy,setStrategy]=useState('INDEPENDENT');
 return <div className="production-layout"><SceneRail scenes={scenes} sceneId={sceneId} setSceneId={setSceneId}/><div className="production-center"><div className="section-intro"><div><span className="small-label">PRODUCTION PLAN</span><h2>{scene?.payload.place||'选择场次'} <span className="heading-count">制作计划</span></h2><p>镜头表达导演意图；Clip 决定怎样交给当前模型执行。</p></div><Badge tone="gold">H3 · 480P · 20 STEPS</Badge></div>
 {provider?.h3!=='可用'&&<div className="offline-banner"><CircleAlert size={19}/><div><strong>H3 视频服务：{provider?.h3||'检查中'}</strong><span>{provider?.h3_message||'镜头与制作计划可以继续编辑。'}</span></div></div>}
 {!scene&&<Empty icon={ClipboardList} title="先选择一个场次" body="从 01 剧本和 03 镜头开始。"/>}
 {scene&&shots.length===0&&<Empty icon={Layers3} title="先确认镜头计划" body="在 03 写下这场戏怎样拍，再来决定生成方式。"/>}
 {scene&&shots.length>0&&clips.length===0&&<Empty icon={ClipboardList} title="还没有 Clip 计划" body="根据已确认的导演镜头，规划模型每次生成的片段。"/>}
 <div className="clip-stack">{clips.map((clip,i)=><ClipPanel key={clip.id} clip={clip} index={i} base={base} shots={shots} jobs={jobs.filter(j=>j.snapshot?.task?.clip_id===clip.id)} provider={provider} act={act}/>)}</div>
 {scene&&shots.length>0&&<section className="panel add-clip"><div className="panel-title"><div><span className="small-label">GENERATION UNIT</span><h2>添加生成片段</h2></div></div><div className="form-grid"><Field label="片段名称" value={name} onChange={setName} placeholder="例如：Clip A"/><Field label="目标时长（秒）" value={duration} onChange={setDuration}/></div><label className="field"><span>生成策略</span><select value={strategy} onChange={e=>setStrategy(e.target.value)}>{STRATEGIES.map(s=><option key={s} value={s}>{STRATEGY_NAME[s]}</option>)}</select></label><p className="hint">一个 Clip 可以包含多个 Shot；长 Shot 也可以按区间进入多个 Clip。</p><button className="secondary" disabled={Number(duration)<=0} onClick={()=>act(async()=>{await post(`${base}/clips`,{payload:{scene_id:sceneId,name:name||`Clip ${clips.length+1}`,duration:Number(duration),handoff:strategy}});setName('');},'Clip 已加入制作计划')}><Plus size={16}/> 创建 Clip</button></section>}</div></div>;
}
function ClipPanel({clip,index,base,shots,jobs,provider,act}:{clip:Clip;index:number;base:string;shots:Entity[];jobs:any[];provider:Provider|null;act:any}) {
 const [open,setOpen]=useState(false);const [ready,setReady]=useState<any>(null);const [mapShot,setMapShot]=useState('');const [start,setStart]=useState('0');const [end,setEnd]=useState('');const [clipStart,setClipStart]=useState('0');const [cut,setCut]=useState(false);
 const [handoffKind,setHandoffKind]=useState('state');const [handoffSecond,setHandoffSecond]=useState('0');const [handoffDuration,setHandoffDuration]=useState('3');const [assessment,setAssessment]=useState('');
 const cid=clip.id;const selectedShot=shots.find(s=>s.id===mapShot);
 useEffect(()=>{get(`${base}/clips/${cid}/readiness`).then(setReady).catch(()=>setReady(null));},[base,cid,clip.mappings.length,open]);
 const currentJob=jobs[0];const needsDependency=clip.dependencies.some(d=>d.kind==='VIDEO_CONTINUATION');
 const generated=clip.take_count>0;
 const statusText=currentJob?.status==='failed'?'生成失败': currentJob?.status==='running'?'生成中':generated?'已有候选':provider?.h3!=='可用'?'模型服务未启动':ready?.status==='READY'?'可以生成':needsDependency?'等待上一片段确认':'制作方案未就绪';
 return <article className="clip-panel"><button className="clip-summary" onClick={()=>setOpen(!open)} aria-expanded={open}><div className="clip-order">{String(index+1).padStart(2,'0')}</div><div className="clip-main"><div className="clip-heading"><h3>{clip.payload.name||`Clip ${clip.id}`}</h3><Badge tone={generated?'green':currentJob?.status==='failed'?'red':ready?.status==='READY'?'gold':'neutral'}>{statusText}</Badge></div><p>{STRATEGY_NAME[clip.payload.handoff]||clip.payload.handoff} <span className="dot-separator">·</span> {clip.payload.duration}s <span className="dot-separator">·</span> {clip.mappings.length} 个 Shot</p><div className="mapping-chips">{clip.mappings.map(m=><span key={m.ordinal}>{m.shot_id}{m.shot_start>0||m.shot_end!==shots.find(s=>s.id===m.shot_id)?.payload.duration?` ${m.shot_start}–${m.shot_end}s`:''}</span>)}{clip.mappings.length===0&&<span className="empty-chip">尚未关联 Shot</span>}</div></div><ChevronDown className={open?'rotated':''} size={19}/></button>
 {open&&<div className="clip-expanded"><div className="clip-meta-grid"><div><span>生成策略</span><strong>{STRATEGY_NAME[clip.payload.handoff]||clip.payload.handoff}</strong></div><div><span>当前模型</span><strong>MiniMax H3</strong></div><div><span>交接</span><strong>{needsDependency?'等待上一片段采用 + Stable Tail':'独立或状态承接'}</strong></div><div><span>参考素材</span><strong>以最终制作方案为准</strong></div></div>
 <div className="shot-map-box"><div className="subheading"><strong>Shot → Clip</strong><span>导演镜头在本片段中的时间范围</span></div>{clip.mappings.length===0?<p className="muted">还没有 Shot 映射。</p>:clip.mappings.map(m=><div className="mapping-row" key={m.ordinal}><span className="mapping-line"/><strong>{m.shot_id}</strong><span>{m.shot_start}–{m.shot_end}s</span><ArrowRight size={15}/><strong>{clip.payload.name||'当前 Clip'}</strong><span>{m.clip_start}–{m.clip_end}s</span>{m.cut_before&&<Badge>CUT</Badge>}</div>)}<div className="mapping-form"><label>镜头<select aria-label="映射镜头" value={mapShot} onChange={e=>{setMapShot(e.target.value);setEnd(String(shots.find(s=>s.id===e.target.value)?.payload.duration||''));}}><option value="">选择 Shot</option>{shots.map(s=><option key={s.id} value={s.id}>{s.id} · {s.payload.description}</option>)}</select></label><label>镜头起点<input aria-label="镜头起点" type="number" value={start} onChange={e=>setStart(e.target.value)}/></label><label>镜头终点<input aria-label="镜头终点" type="number" value={end} onChange={e=>setEnd(e.target.value)}/></label><label>Clip 起点<input aria-label="片段起点" type="number" value={clipStart} onChange={e=>setClipStart(e.target.value)}/></label><label className="checkbox"><input type="checkbox" checked={cut} onChange={e=>setCut(e.target.checked)}/> CUT</label><button className="secondary small" disabled={!selectedShot||!end} onClick={()=>act(async()=>{await post(`${base}/clips/${cid}/mappings`,{shot_id:mapShot,ordinal:clip.mappings.length,shot_start:Number(start),shot_end:Number(end),clip_start:Number(clipStart),clip_end:Number(clipStart)+Number(end)-Number(start),cut_before:cut});setMapShot('');setStart('0');setEnd('');setClipStart(String(Number(clipStart)+Number(end)-Number(start)));},'Shot 已关联 Clip')}>添加映射</button>{clip.mappings.length>0&&<button className="ghost small" onClick={()=>{if(confirm("清空当前 Shot 映射并重新规划？旧映射保留在历史版本中。"))act(()=>request(`${base}/clips/${cid}/mappings?expected_revision=${clip.mapping_revision}`,{method:"PUT",body:JSON.stringify([])}),"映射已清空，需重新规划");}}>清空并重排</button>}</div></div>
 <BriefEditor base={base} clip={clip} shots={shots} act={act}/>
 {clip.dependencies.length>0&&<div className="handoff-box"><div className="subheading"><strong>与上一段的衔接</strong><span>先采用上游 Take 并确认实际状态</span></div><p className="muted">{clip.dependencies.map(d=>`等待 ${d.upstream_clip_id}`).join('、')}。普通 CUT 只承接世界状态；同一长镜头续接需要人工检查真实 Stable Tail。</p><div className="mapping-form"><label>准备方式<select value={handoffKind} onChange={e=>setHandoffKind(e.target.value)}><option value="state">仅承接实际状态</option>{!needsDependency&&<option value="visual_anchor">选择稳定画面</option>}{needsDependency&&<option value="stable_tail">选择稳定尾段</option>}</select></label>{handoffKind!=='state'&&<><label>视频起点秒<input type="number" min="0" step="0.1" value={handoffSecond} onChange={e=>setHandoffSecond(e.target.value)}/></label>{handoffKind==='stable_tail'&&<label>尾段秒数<input type="number" min="2" max="15" step="0.1" value={handoffDuration} onChange={e=>setHandoffDuration(e.target.value)}/></label>}</>}<label>人工检查说明<input value={assessment} onChange={e=>setAssessment(e.target.value)} placeholder="身份、道具、空间与运动稳定"/></label><button className="secondary small" disabled={handoffKind!=='state'&&!assessment.trim()} onClick={()=>act(()=>post(`${base}/clips/${cid}/prepare-handoff`,{upstream_clip_id:clip.dependencies[0].upstream_clip_id,kind:handoffKind,at_second:Number(handoffSecond),duration:Number(handoffDuration),assessment:assessment||'已确认实际状态'}),'衔接准备已保存为新制作方案版本')}>准备衔接</button></div></div>}
 <div className="generation-box"><div><span className="small-label">GENERATION</span><h4>生成任务</h4><p>{provider?.h3!=='可用'?provider?.h3_message:currentJob?.status==='failed'?'上一次提交失败。确认服务已开启后，可显式提交一条新任务；原失败记录保留。':ready?.status==='READY'?'制作方案通过检查，可提交单个候选。':(ready?.reasons||[]).map(prettyReason).join('；')||'先完成最终制作方案。'}</p></div><div className="generation-actions"><button className="primary" disabled={provider?.h3!=='可用'||ready?.status!=='READY'||currentJob?.status==='running'} onClick={()=>act(()=>post(`${base}/clips/${cid}/generate${currentJob?.status==='failed'?`?retry_of=${encodeURIComponent(currentJob.id)}`:''}`),'生成任务已提交，预计约 3 分钟；请稍后手动刷新。')}><Video size={16}/> {currentJob?.status==='failed'?'确认并重试一条':'生成一条'}</button></div></div>
 {jobs.length>0&&<div className="job-history"><strong>任务记录</strong>{jobs.map(j=><div key={j.id}><span>{j.id}</span><Badge tone={j.status==='failed'?'red':j.status==='succeeded'?'green':'gold'}>{j.status}</Badge>{j.metadata?.provider_error&&<small>{j.metadata.provider_error.code==='fail_to_fetch_task'?'H3 服务未启动':j.metadata.provider_error.message}</small>}{j.status==='running'&&<button className="text-button" onClick={()=>act(()=>post(`${base}/jobs/${j.id}/sync`),'已查询任务状态')}>手动刷新</button>}</div>)}</div>}
 </div>}</article>;
}
function BriefEditor({base,clip,shots,act}:{base:string;clip:Clip;shots:Entity[];act:any}) {
 const [briefs,setBriefs]=useState<Entity[]>([]);const [qa,setQa]=useState<any>(null);
 const [world,setWorld]=useState<Record<string,Entity[]>>({});const [assetId,setAssetId]=useState('');const [referenceRole,setReferenceRole]=useState('character_look');
 const [purpose,setPurpose]=useState('');const [stateIn,setStateIn]=useState('');const [initial,setInitial]=useState('');const [trigger,setTrigger]=useState('');const [development,setDevelopment]=useState('');const [result,setResult]=useState('');const [performance,setPerformance]=useState('');const [camera,setCamera]=useState('');const [sound,setSound]=useState('');const [ending,setEnding]=useState('');const [environment,setEnvironment]=useState('');const [character,setCharacter]=useState('');const [look,setLook]=useState('');const [location,setLocation]=useState('');
 const [edit,setEdit]=useState(false);const latestBrief=briefs[0];
 useEffect(()=>{Promise.all([get<Entity[]>(`${base}/clips/${clip.id}/briefs`),get(`${base}/clips/${clip.id}/readiness`),...['character','character_look','location','asset_version'].map(k=>get<Entity[]>(`${base}/world/${k}`))]).then(([bb,qq,ch,looks,locations,assets])=>{setBriefs(bb);setQa(qq);setWorld({character:ch,character_look:looks,location:locations,asset_version:assets});}).catch(()=>{});},[base,clip.id,clip.mappings.length,edit]);
 useEffect(()=>{if(!latestBrief)return;const p=latestBrief.payload;setPurpose(p.purpose||'');setStateIn(p.state_in?.facts?.summary||JSON.stringify(p.state_in?.facts||{}));setInitial(p.action_process?.[0]?.initial||'');setTrigger(p.action_process?.[0]?.trigger||'');setDevelopment(p.action_process?.[0]?.development||'');setResult(p.action_process?.[0]?.result||'');setPerformance(Object.values(p.performance||{}).join('；'));setCamera([p.camera?.framing,p.camera?.movement].filter(Boolean).join('；'));setSound(p.sound?.diegetic||'');setEnding(p.planned_state_out?.summary||JSON.stringify(p.planned_state_out||{}));setEnvironment(p.environment?.description||'');setCharacter(p.subjects?.[0]?.character_id||'');setLook(p.subjects?.[0]?.look_id||'');setLocation(p.environment?.location_id||'');},[latestBrief?.version]);
 const mappingTimeline=clip.mappings.map(m=>({shot_id:m.shot_id,start:m.clip_start,end:m.clip_end,shot_start:m.shot_start,shot_end:m.shot_end,cut_before:!!m.cut_before,description:shots.find(s=>s.id===m.shot_id)?.payload.description||''}));
 async function save(){
 const old=latestBrief?.payload||{};
 const oldIn=old.state_in?.facts?.summary||JSON.stringify(old.state_in?.facts||{});
 const oldOut=old.planned_state_out?.summary||JSON.stringify(old.planned_state_out||{});
 const oldPerf=Object.values(old.performance||{}).join('；');
 const oldCamera=[old.camera?.framing,old.camera?.movement].filter(Boolean).join('；');
 const payload={...old,clip_id:clip.id,scene_id:clip.payload.scene_id,duration:clip.payload.duration,
   shot_timeline:mappingTimeline,purpose,
   subjects:character&&look?[{character_id:character,look_id:look}]:[],
   environment:{...(old.environment||{}),location_id:location,description:environment},
   props:old.props||[],
   state_in:stateIn===oldIn&&old.state_in?old.state_in:{source:'scene_initial',facts:stateIn.trim()?{summary:stateIn}:{}},
   action_process:[{initial,trigger,development,result}],
   performance:performance===oldPerf&&old.performance?old.performance:{gesture:performance},
   camera:camera===oldCamera&&old.camera?old.camera:{framing:camera,movement:camera},
   sound:{...(old.sound||{}),diegetic:sound},
   references:old.references||[],constraints:old.constraints||[],locked_constraints:old.locked_constraints||[],
   planned_state_out:ending===oldOut&&old.planned_state_out?old.planned_state_out:{summary:ending},
   handoff:clip.payload.handoff,provenance:{source:'creator-approved-production-plan',authority:'PLANNED'}};
 await act(async()=>{await post(`${base}/clips/${clip.id}/briefs`,{payload,expected_version:latestBrief?.version||null,status:'approved'});setEdit(false);},'最终制作方案新版本已保存');}
 return <section className="brief-box"><div className="brief-heading"><div><span className="small-label">FINAL GENERATION BRIEF</span><h4>最终制作方案</h4></div><div><Badge tone={qa?.status==='READY'?'green':'red'}>{qa?.status||'检查中'}</Badge><button className="text-button" onClick={()=>setEdit(!edit)}>{edit?'收起编辑':'编辑方案'} <ChevronDown size={15}/></button></div></div>
 {!latestBrief&&!edit&&<p className="muted">还没有制作方案。先关联 Shot，再填写生成前需要确定的内容。</p>}
 {latestBrief&&!edit&&<div className="brief-readable"><div><span>01 · 这一段的目的</span><strong>{latestBrief.payload.purpose}</strong></div><div><span>02 · 时间线</span><strong>{latestBrief.payload.shot_timeline?.map((s:any)=>`${s.shot_id} ${s.start}–${s.end}s${s.cut_before?' · CUT':''}`).join(' → ')||'待填写'}</strong></div><div><span>03 · 人物 / 世界 / 道具</span><strong>{latestBrief.payload.subjects?.map((s:any)=>s.character_id).join('、')||'待确认'} · {latestBrief.payload.environment?.description||latestBrief.payload.environment?.location_id||'待确认'}</strong></div><div><span>04 · 开始状态</span><strong>{latestBrief.payload.state_in?.facts?.summary||latestBrief.payload.state_in?.source||'待确认'}</strong></div><div><span>05 · 动作过程</span><strong>{latestBrief.payload.action_process?.map((a:any)=>[a.initial,a.trigger,a.development,a.result].join(' → ')).join('；')}</strong></div><div><span>06 · 表演</span><strong>{Object.values(latestBrief.payload.performance||{}).join('；')}</strong></div><div><span>07 · 摄影</span><strong>{Object.values(latestBrief.payload.camera||{}).join('；')}</strong></div><div><span>08 · 声音</span><strong>{latestBrief.payload.sound?.diegetic}</strong></div><div><span>09 · 参考素材</span><strong>{latestBrief.payload.references?.length?`${latestBrief.payload.references.length} 个真实绑定`:'无参考素材'}</strong></div><div><span>10 · 结束状态</span><strong>{latestBrief.payload.planned_state_out?.summary||JSON.stringify(latestBrief.payload.planned_state_out)}</strong></div><div><span>11 · 衔接</span><strong>{STRATEGY_NAME[latestBrief.payload.handoff]||latestBrief.payload.handoff}</strong></div></div>}
 {edit&&<div className="brief-form"><Field label="这一段的目的" value={purpose} onChange={setPurpose} multiline/><div className="brief-timeline">时间线：{mappingTimeline.length?mappingTimeline.map(t=>`${t.shot_id} ${t.start}–${t.end}s`).join(' → '):'先关联 Shot'}</div><div className="form-grid"><label className="field"><span>人物</span><select value={character} onChange={e=>setCharacter(e.target.value)}><option value="">选择人物</option>{(world.character||[]).map(x=><option key={x.id} value={x.id}>{x.payload.name}</option>)}</select></label><label className="field"><span>造型</span><select value={look} onChange={e=>setLook(e.target.value)}><option value="">选择造型</option>{(world.character_look||[]).map(x=><option key={x.id} value={x.id}>{x.payload.description||x.id}</option>)}</select></label><label className="field"><span>场景身份</span><select value={location} onChange={e=>setLocation(e.target.value)}><option value="">选择场景</option>{(world.location||[]).map(x=><option key={x.id} value={x.id}>{x.payload.identity}</option>)}</select></label></div><Field label="当前场景状态" value={environment} onChange={setEnvironment} placeholder="时间、天气、灯光"/><Field label="片段开始时的实际状态" value={stateIn} onChange={setStateIn} multiline placeholder="人物位置、持物、情绪与上一段衔接"/><div className="form-grid"><Field label="动作开始" value={initial} onChange={setInitial}/><Field label="触发" value={trigger} onChange={setTrigger}/><Field label="发展" value={development} onChange={setDevelopment}/><Field label="结果" value={result} onChange={setResult}/></div><Field label="表演 · 可见细节" value={performance} onChange={setPerformance} multiline/><Field label="摄影 · 景别与运动" value={camera} onChange={setCamera} multiline/><Field label="声音" value={sound} onChange={setSound}/><Field label="计划结束状态" value={ending} onChange={setEnding}/><button className="primary" onClick={save}><Save size={16}/> 保存新版本</button></div>}
 {qa?.reasons?.length>0&&<div className="qa-reasons"><strong>生成前还需完成</strong><ul>{qa.reasons.map((r:any,i:number)=><li key={i}>{prettyReason(r)}</li>)}</ul></div>}
 {latestBrief&&<div className="reference-plan"><div className="subheading"><strong>真实参考素材</strong><span>素材来源与本次用途分开保存</span></div><div className="mapping-form"><label>素材版本<select value={assetId} onChange={e=>setAssetId(e.target.value)}><option value="">选择已上传图片</option>{(world.asset_version||[]).map(a=><option key={`${a.id}-${a.version}`} value={`${a.id}@${a.version}`}>{a.payload.purpose||a.id} · V{a.version}{a.is_current?' · 当前':''}</option>)}</select></label><label>这次的作用<select value={referenceRole} onChange={e=>setReferenceRole(e.target.value)}><option value="character_look">人物造型</option><option value="character_identity">人物身份</option><option value="environment_identity">场景身份</option><option value="prop_identity">道具身份</option><option value="composition_reference">构图参考</option><option value="first_frame">首帧</option><option value="last_frame">尾帧</option></select></label><button className="secondary small" disabled={!assetId} onClick={()=>act(async()=>{const [id,version]=assetId.split('@');await post(`${base}/clips/${clip.id}/references`,{asset_id:id,asset_version:Number(version),role:referenceRole});setBriefs(await get(`${base}/clips/${clip.id}/briefs`));setAssetId('');},'参考素材已绑定到新方案版本')}>绑定参考</button></div><p className="hint">参考图不会自动成为首帧；首帧需要明确选择。</p></div>}
 <details className="advanced"><summary>高级执行信息</summary><p>Brief version {latestBrief?.version||'—'} · H3 compiler 在提交生成时读取已确认的制作方案。Raw Prompt 与 provider payload 不作为项目真相。</p></details></section>;
}
function ReviewSpace({base,clips,clipId,setClipId,takes,reality,act}:{base:string;clips:Clip[];clipId:string;setClipId:any;takes:any[];reality:Record<string,any>;act:any}) {
 const clip=clips.find(c=>c.id===clipId);const clipTakes=takes.filter(t=>t.clip_id===clipId);const [takeId,setTakeId]=useState('');const [actual,setActual]=useState('');const [observedId,setObservedId]=useState('');const [showConfirm,setShowConfirm]=useState(false);const [planned,setPlanned]=useState('');
 useEffect(()=>{setTakeId(clipTakes[0]?.id||'');setObservedId('');setActual('');},[clipId,takes.length]);
 useEffect(()=>{if(!clipId){setPlanned('');return;}get<any[]>(`${base}/clips/${clipId}/briefs`).then(rows=>setPlanned(rows[0]?.payload?.planned_state_out?.summary||'未在最终制作方案中填写')).catch(()=>setPlanned('暂时无法读取计划状态'));},[base,clipId]);
 const take=clipTakes.find(t=>t.id===takeId);const selected=reality[clipId]?.selection;
 return <div className="review-space"><div className="review-top"><div><span className="small-label">HUMAN REVIEW</span><h2>选择真正能进入影片的片段</h2></div><label className="review-select"><span>当前 Clip</span><select value={clipId} onChange={e=>setClipId(e.target.value)}>{clips.map(c=><option key={c.id} value={c.id}>{c.payload.name||c.id}</option>)}</select></label></div>
 {!clips.length&&<Empty icon={Play} title="还没有待审的片段" body="先在 04 制定 Clip 计划并生成真实视频。"/>}
 {clip&&!clipTakes.length&&<Empty icon={Video} title="此片段还没有真实 Take" body="审片区只播放实际生成并保存的媒体。可以回到 04 检查任务或继续制作方案。" action={<Link className="secondary" href={`${base.replace('/projects/','/projects/')}/04`}>前往影片制作 <ArrowRight size={15}/></Link>}/>}
 {clip&&clipTakes.length>0&&<div className="review-grid"><div className="review-main"><div className="player-frame">{take?.media_id&&!take.test_only?<video controls preload="metadata" key={take.id} src={`${API}/api/media/${take.media_id}`}/>:<div className="player-unavailable"><Video size={30}/><span>测试结果或媒体不可播放</span></div>}</div><div className="review-player-caption"><div><strong>{clip.payload.name||clip.id}</strong><span>{take?.id} · {take?.test_only?'TEST ONLY':'真实媒体'}</span></div><Badge tone={selected?.take_id===takeId?'green':'neutral'}>{selected?.take_id===takeId?'当前采用':'候选'}</Badge></div><div className="review-decision"><h3>这条我要吗？</h3><p>请看完整段落，判断表演、镜头、声音与连续性是否成立。AI 不替你做采用决定。</p><div className="button-row"><button className="primary" disabled={!take} onClick={()=>act(()=>post(`${base}/clips/${clipId}/selection`,{take_id:takeId,actor:'local-creator'}),'已采用此 Take；请记录实际结束状态。')}><Check size={16}/> 采用这条</button><Link href={`/projects/${base.split('/').pop()}/04`} className="secondary">修改制作方案</Link></div></div></div><aside className="review-side"><section className="panel"><div className="panel-title"><h3>候选 Take</h3><Badge>{clipTakes.length}</Badge></div><div className="take-list">{clipTakes.map((t,i)=><button key={t.id} className={takeId===t.id?'active':''} onClick={()=>setTakeId(t.id)}><span className="take-icon"><Play size={16}/></span><span><strong>Take {String(i+1).padStart(2,'0')}</strong><small>{t.id}</small></span>{selected?.take_id===t.id&&<Check size={16}/>}</button>)}</div></section><section className="panel"><div className="panel-title"><h3>实际影片状态</h3></div>{!selected?<p className="muted">先采用一条 Take，才能记录实际发生了什么。</p>:<><p className="muted">实际结尾与计划不同也可以接受，但必须由你明确确认。</p>{reality[clipId]?.canonical&&<div className="canonical-current"><Badge tone="green">已确认</Badge><p>{reality[clipId].canonical.payload.summary||JSON.stringify(reality[clipId].canonical.payload)}</p></div>}<div className="state-diff"><span>制作方案计划结尾</span><p>{planned||'载入中…'}</p></div><Field label="这条片段实际怎样结束？" value={actual} onChange={setActual} multiline placeholder="例如：左手拿信，停在站台门口；没有哭。"/><button className="secondary" disabled={!actual.trim()||selected.take_id!==takeId} onClick={()=>act(async()=>{const o=await post(`${base}/clips/${clipId}/observed`,{take_id:selected.take_id,state:{summary:actual},observer:'local-creator'});setObservedId(o.id);setShowConfirm(true);},'实际状态已记录，等待确认')}>记录观察</button>{selected.take_id!==takeId&&<p className="hint">正在查看其他候选。请先采用这条，再记录它的实际状态。</p>}{showConfirm&&observedId&&<div className="confirm-state"><strong>{planned.trim()===actual.trim()?'实际结尾与计划一致，确认给下一片段继承？':'实际结尾与计划不同，接受这个实际结果并让下一片段据此继续？'}</strong><p>计划：{planned}</p><p>实际：{actual}</p><div className="button-row"><button className="primary small" onClick={()=>act(async()=>{await post(`${base}/clips/${clipId}/canonical/${observedId}?actor=local-creator`);setShowConfirm(false);},'实际状态已成为影片正式状态')}>接受实际结果</button><Link className="secondary small" href={`/projects/${base.split('/').pop()}/04`}>修改计划</Link><button className="ghost" onClick={()=>setShowConfirm(false)}>稍后决定</button></div></div>}</>}</section></aside></div>}</div>;
}
function FinalSpace({base,clips,takes,reality,timeline,act}:{base:string;clips:Clip[];takes:any[];reality:Record<string,any>;timeline:any;act:any}) {
 const [active,setActive]=useState(0);const [playingSequence,setPlayingSequence]=useState(false);const [start,setStart]=useState('0');const [end,setEnd]=useState('');const [subtitle,setSubtitle]=useState('');const [subStart,setSubStart]=useState('0');const [subEnd,setSubEnd]=useState('3');const [preview,setPreview]=useState('');
 const selected=clips.map(c=>({clip:c,selection:reality[c.id]?.selection})).filter(x=>x.selection);
 const item=timeline.items?.[active];const currentTake=takes.find(t=>t.id===item?.take_id);const currentSelection=reality[item?.clip_id]?.selection;
 useEffect(()=>{setStart(String(item?.trim_in??0));setEnd(item?.trim_out==null?'':String(item.trim_out));},[item?.id,item?.trim_in,item?.trim_out]);
 return <div className="final-space"><div className="section-intro"><div><span className="small-label">FINAL TIMELINE</span><h2>让片段成为一部影片</h2><p>时间线引用已采用的 Take；裁切和排序不会修改原始视频。</p></div><button className="secondary" disabled={!timeline.items?.length} onClick={()=>act(async()=>{const p=await post(`${base}/timeline/preview`);setPreview(p.path);},'拼接预览已导出')}>导出预览 <ArrowRight size={16}/></button></div>
 {!timeline.items?.length&&<Empty icon={Film} title="成片时间线还是空的" body="在 05 采用真实 Take 后，就可以将它们按故事顺序放进这里。"/>}
 <div className="final-layout"><section className="panel final-track-panel">{timeline.items?.length>0&&<><div className="final-player">{currentTake?.media_id&&!currentTake.test_only?<video controls autoPlay={playingSequence} preload="metadata" key={item.id+'-'+currentTake.id} src={`${API}/api/media/${currentTake.media_id}`} onLoadedMetadata={e=>{e.currentTarget.currentTime=item.trim_in;e.currentTarget.volume=Math.min(1,item.volume);}} onTimeUpdate={e=>{if(item.trim_out!=null&&e.currentTarget.currentTime>=item.trim_out){e.currentTarget.pause();if(playingSequence&&active<timeline.items.length-1)setActive(i=>i+1);else setPlayingSequence(false);}}} onEnded={()=>{if(playingSequence&&active<timeline.items.length-1)setActive(i=>i+1);else setPlayingSequence(false);}}/>:<div className="player-unavailable">真实媒体不可用</div>}</div><div className="subheading"><strong>影片序列</strong><span>{timeline.items.length} 个片段</span></div><div className="timeline-track">{timeline.items.map((t:any,i:number)=><button className={`timeline-block ${active===i?'active':''}`} key={t.id} onClick={()=>{setPlayingSequence(false);setActive(i);}}><span>{String(i+1).padStart(2,'0')}</span><strong>{clips.find(c=>c.id===t.clip_id)?.payload.name||t.clip_id}</strong><small>{t.transition} · {t.trim_in}s → {t.trim_out??'结尾'}{takes.find(x=>x.id===t.take_id)?.test_only?" · TEST ONLY":""}</small></button>)}</div><div className="timeline-edit"><button className="secondary small" disabled={timeline.items.some((t:any)=>takes.find(x=>x.id===t.take_id)?.test_only)} onClick={()=>{setActive(0);setPlayingSequence(true);}}>从头连续播放</button><label>起点<input aria-label="裁切起点" type="number" min="0" step="0.1" value={start} onChange={e=>setStart(e.target.value)}/></label><label>终点<input aria-label="裁切终点" type="number" min="0" step="0.1" value={end} onChange={e=>setEnd(e.target.value)}/></label><label>转场<select aria-label="转场" value={item.transition} onChange={e=>act(()=>patch(`${base}/timeline/items/${item.id}`,{transition:e.target.value}),"转场已保存")}><option value="cut">直接 CUT</option><option value="fade">淡入</option></select></label><label>音量<input aria-label="音量" type="number" min="0" max="2" step="0.1" defaultValue={item.volume} onBlur={e=>act(()=>patch(`${base}/timeline/items/${item.id}`,{volume:Number(e.target.value)}),"音量已保存")}/></label><button className="secondary small" onClick={()=>act(()=>patch(`${base}/timeline/items/${item.id}`,{trim_in:Number(start),trim_out:end?Number(end):null}),'裁切已保存')}>保存裁切</button>{currentSelection&&currentSelection.take_id!==item.take_id&&<button className="secondary small" onClick={()=>act(()=>patch(`${base}/timeline/items/${item.id}`,{take_id:currentSelection.take_id}),'已替换为当前采用 Take')}>替换为当前采用</button>}<button className="ghost small" disabled={active===0} onClick={()=>act(()=>patch(`${base}/timeline/items/${item.id}`,{position:item.position-1.5}),'顺序已更新')}>向前移动</button><button className="danger-text" onClick={()=>act(()=>remove(`${base}/timeline/items/${item.id}`),'已从时间线移除')}>移除</button></div></>}
 {preview&&<div className="alert success">本地预览已生成：{preview}</div>}</section><aside className="final-side"><section className="panel"><div className="panel-title"><h3>已采用片段</h3></div>{selected.length===0?<p className="muted">还没有采用的真实 Take。</p>:selected.map(({clip,selection})=><div className="selected-clip" key={clip.id}><div><strong>{clip.payload.name||clip.id}</strong><span>{selection.take_id}{takes.find(t=>t.id===selection.take_id)?.test_only?" · TEST ONLY":""}</span></div><button className="secondary small" onClick={()=>act(()=>post(`${base}/timeline/items`,{clip_id:clip.id,take_id:selection.take_id,trim_in:0,transition:'cut',volume:1}),'片段已加入时间线')}>加入 <Plus size={14}/></button></div>)}</section><section className="panel"><div className="panel-title"><h3>字幕轨</h3></div>{timeline.subtitles?.map((s:any)=><div className="subtitle-row" key={s.id}><span>{s.start}–{s.end}s</span><strong>{s.text}</strong></div>)}<Field label="字幕文字" value={subtitle} onChange={setSubtitle}/><div className="form-grid"><Field label="开始秒" value={subStart} onChange={setSubStart}/><Field label="结束秒" value={subEnd} onChange={setSubEnd}/></div><button className="secondary small" disabled={!subtitle.trim()} onClick={()=>act(async()=>{await post(`${base}/timeline/subtitles`,{text:subtitle,start:Number(subStart),end:Number(subEnd)});setSubtitle('');},'字幕已加入')}>添加字幕</button></section></aside></div></div>;
}
